#include "render/LightingPolicy.hpp"
#include "core/Saturating.hpp"
#include <algorithm>
#include <cmath>
namespace elysium::render {LightingFramePacket LightingPolicy::build(const LightingSnapshot&s,const LightingPolicyConfig&c,std::uint32_t geometryLod)const{(void)geometryLod;LightingFramePacket o;o.directional=s.directional;o.directional.sunIntensity=elysium::safe::nonNegative(o.directional.sunIntensity);o.directional.skyIntensity=elysium::safe::nonNegative(o.directional.skyIntensity);o.fog=s.fog;o.fog.density=elysium::safe::nonNegative(o.fog.density);o.fog.hazardDensity=elysium::safe::nonNegative(o.fog.hazardDensity);o.fog.visibilityFloor=elysium::safe::nonNegative(o.fog.visibilityFloor);o.quality=c.quality;o.indirectLightExperiment=c.enableIndirectLightExperiment&&c.profilingGatePassed;for(auto l:s.local){l.radius=elysium::safe::nonNegative(l.radius);l.intensity=elysium::safe::nonNegative(l.intensity);if(!l.stableId||l.radius<=0||l.intensity<=0)continue;o.lights.push_back(l);}std::stable_sort(o.lights.begin(),o.lights.end(),[](auto&a,auto&b){if(a.gameplayCritical!=b.gameplayCritical)return a.gameplayCritical>b.gameplayCritical;if(a.castsShadow!=b.castsShadow)return a.castsShadow>b.castsShadow;if(a.intensity!=b.intensity)return a.intensity>b.intensity;return a.stableId<b.stableId;});for(auto&l:o.lights)if(l.castsShadow&&o.shadowCasters.size()<c.shadows.maxCasters)o.shadowCasters.push_back(l);return o;}}
